function isForsakenDepthsRulesetSelected() {
  const profile = selectedRulesetProfile();
  if (profile) return profile.ruleset === "forsaken_depths";
  return rulesetSelect?.value?.startsWith("forsaken_depths") === true;
}

function syncRulesetControls() {
  const randomAdventure = adventureSelect?.value === "random";
  const fdSelected = randomAdventure && isForsakenDepthsRulesetSelected();
  rulesetSelect?.closest("label")?.classList.toggle("hidden", !randomAdventure);
  courtshipEnabled?.closest("label")?.classList.add("hidden");
  rulesetHint?.classList.toggle("hidden", !randomAdventure);
  const profile = selectedRulesetProfile();
  if (rulesetHint && profile?.description) {
    rulesetHint.textContent = profile.description;
    setTooltip(rulesetHint, profile.description);
  } else if (rulesetHint && fdSelected) {
    setTooltip(rulesetHint, SETUP_TOOLTIPS.rulesetHint);
  } else if (rulesetHint) {
    setTooltip(rulesetHint, "");
  }
  fiendishFoesPrefs?.classList.toggle("hidden", fdSelected);
  syncFiendishFoesControls();
}

function fdMapModeLabel(session) {
  if (session?.ruleset !== "forsaken_depths") return "";
  if (session.tile_catalog === "forsaken_depths_rivers") return "FD · Underground river";
  return "FD · Dungeon";
}

const FD_RIVER_TYPE_LABELS = {
  oblivion: "River of Oblivion",
  tears: "River of Tears",
  death: "River of Death",
  flame: "River of Flame",
  conjuration: "River of Conjuration",
  serpent: "Serpent River",
};

function fdRiverTypeDisplay(session) {
  const key = session?.fd_river_type;
  if (!key) return "";
  return FD_RIVER_TYPE_LABELS[key] || key;
}

function fdBoatStatusDisplay(session) {
  if (session?.ruleset !== "forsaken_depths") return "";
  const status = session.fd_boat_status || "ok";
  if (status === "ok" && session.tile_catalog !== "forsaken_depths_rivers") return "";
  if (status === "ok") return "Boat: OK";
  if (status === "damaged") return "Boat: Damaged";
  return "Boat: Destroyed";
}

function fdTravelModeDisplay(session) {
  if (session?.ruleset !== "forsaken_depths") return "";
  if (session.tile_catalog !== "forsaken_depths_rivers") return "";
  if (session.fd_travel_mode === "foot" || session.fd_boat_status === "destroyed") return "Travel: On foot";
  if (session.fd_boat_status === "damaged") return "Travel: Boat (damaged)";
  return "Travel: Boat";
}

const FD_CITADEL_LABELS = {
  ghost_citadel: "Ghost Citadel",
  crowded_citadel: "Crowded Citadel",
  citadel_of_traps: "Citadel of Traps",
  prisoners_citadel: "Prisoners of the Citadel",
  citadel_of_dead: "Citadel of Dead Things",
  magic_citadel: "Magic Citadel",
};

function fdCitadelDisplay(session) {
  if (session?.ruleset !== "forsaken_depths" || !session.fd_citadel_type) return "";
  const name = FD_CITADEL_LABELS[session.fd_citadel_type] || session.fd_citadel_type.replace(/_/g, " ");
  const rooms = session.fd_citadel_room_count;
  return rooms != null ? `Citadel: ${name} (${rooms} rooms)` : `Citadel: ${name}`;
}

function fdStirsDisplay(session) {
  if (session?.ruleset !== "forsaken_depths") return "";
  const remaining = session.fd_stirs_in_darkness_remaining || 0;
  if (!remaining) return "";
  return `Stirs: ${remaining} area${remaining === 1 ? "" : "s"} left`;
}

function fdSideSheetDisplay(session) {
  if (session?.ruleset !== "forsaken_depths" || !session.fd_side_sheet_active) return "";
  const kind = session.fd_side_sheet_kind === "ruins" ? "Ruins" : "Citadel";
  const entered = session.fd_side_sheet_rooms_entered || 0;
  const total = session.fd_side_sheet_rooms_total || 0;
  return `${kind} sheet ${entered}/${total}`;
}

function fdCitadelModifierLine(session) {
  if (!session?.fd_side_sheet_active || session.fd_side_sheet_kind !== "citadel" || !session.fd_citadel_type) {
    return "";
  }
  const hints = {
    ghost_citadel: "Final room: Citadel Weird Final Boss (FD p.60).",
    crowded_citadel: "Double minion counts; −1 Reaction (FD p.60).",
    citadel_of_traps: "Minions often replaced by traps with treasure (FD p.60).",
    prisoners_citadel: "Escape with 4 Clues (map panel button, FD p.60).",
    citadel_of_dead: "No healing except bandages (FD p.60).",
    magic_citadel: "Magic resistance suspended; idols/altars; final Cyclopean Idol (FD p.60).",
  };
  return hints[session.fd_citadel_type] || "";
}

function fdCitadelModifierTooltip(session) {
  const line = fdCitadelModifierLine(session);
  if (line) return line;
  if (session?.fd_citadel_type) {
    const name = FD_CITADEL_LABELS[session.fd_citadel_type] || session.fd_citadel_type.replace(/_/g, " ");
    return `${name} — enter the side sheet from ETC or Passage event (FD p.60).`;
  }
  return "Citadel type and room count from ETC or The Passage event (FD p.60).";
}

function appendFdCitadelSideSheetActions(parent, session) {
  if (session?.fd_citadel_type === "citadel_of_dead" && session.fd_side_sheet_active) {
    const deadLine = subline("Citadel of Dead Things: only bandages heal Life here");
    setTooltip(deadLine, "Rest, potions, and paladin prayer do not restore Life on this side sheet (FD p.60).");
    parent.appendChild(deadLine);
  }
  if (!fdPrisonersEscapeAvailable(session)) return;
  const escapeBtn = node("button", "secondary", "Escape citadel (4 Clues)");
  escapeBtn.type = "button";
  setButtonTooltip(escapeBtn, ACTION_TOOLTIPS.fdPrisonersEscape);
  escapeBtn.addEventListener("click", () => advance("fd_prisoners_escape"));
  parent.appendChild(escapeBtn);
}

const COURTSHIP_REGION_LABELS = {
  seaside: "Seaside",
  riverside: "Riverside",
  meadows: "Meadows",
  woods: "Woods",
  mountain: "Mountain",
  palace: "Queen's Garden Palace",
};

function courtshipHasPandora(session) {
  return (session?.courtship_keywords || []).some(
    (keyword) => String(keyword).toUpperCase() === "PANDORA"
  );
}

function courtshipApothecaryBrewAvailable(session) {
  if (!session?.courtship_enabled) return false;
  if (session.mode !== "exploration" || session.courtship_woo_active) return false;
  if (session.courtship_apothecary_brew_locked) return false;
  if (!session.courtship_demesne_active && !session.camped_outside) return false;
  return (session.party || []).some((member) => {
    if (member.current_life <= 0) return false;
    const classId = String(member.class_id || "").toLowerCase();
    if (classId !== "wandering_alchemist" && classId !== "wandering alchemist") return false;
    return (member.inventory || []).some(
      (item) => /mortar/i.test(item) && /pestle/i.test(item)
    );
  });
}

function abyssPlotNextStep(plot) {
  if (!plot) return "";
  if (plot.completed) return "Completed.";
  if (plot.finale_pending === "assassins_ambush") return "Resolve the assassins' delivery ambush from the room panel.";
  if (plot.finale_pending === "rebellion_war") {
    const total = Number(plot.rebellion_battles_total || 0);
    const resolved = Number(plot.rebellion_battles_resolved || 0);
    return total > 0
      ? `Resolve the rebellion battles from the room panel (${resolved}/${total} complete).`
      : "Resolve the rebellion battles from the room panel.";
  }
  if (plot.finale_pending === "destroy_artifact") return "Defeat the Final Boss, then destroy the artefact through the portal.";
  if (plot.finale_pending === "kidnap_bosses") return "Leave the dungeon to trigger the two-boss ambush.";
  if (plot.finale_pending === "enchantress_lich") return "Leave the dungeon to trigger the enchantress Lich ambush.";
  if (plot.key === "assassination") return `Defeat Final Bosses and collect evidence (${plot.progress || 0}/3).`;
  if (plot.key === "rebellion") return `Fund the rebellion (${plot.gold_contributed || 0}/3000gp).`;
  if (plot.key === "entity") return `Claim one artefact piece per dungeon from magic item treasure (${plot.progress || 0}/3).`;
  if (plot.key === "invasion") return `Spend 9 Clues, keep the artefact carrier alive, then defeat the Final Boss (${plot.artifact_clues_spent || 0}/9).`;
  if (plot.key === "kidnap") return plot.chosen_one_rescued ? "Leave the dungeon for the finale." : "Find corridor non-undead minions holding the chosen one.";
  if (plot.key === "enchantment") return `Collect dragon blood from Final Boss dragons (${plot.progress || 0}/3).`;
  return "Continue the active Abyss plot.";
}

function renderAbyssCampaignStatus(campaign = state.campaign) {
  if (!abyssCampaignStatus) return;
  abyssCampaignStatus.innerHTML = "";
  const plot = campaign?.abyss_campaign_plot;
  const sire = campaign?.abyss_vampire_sire;
  const completed = Array.isArray(campaign?.abyss_campaign_completed_plots)
    ? campaign.abyss_campaign_completed_plots
    : [];
  if (!plot && !sire && !completed.length) {
    abyssCampaignStatus.classList.add("hidden");
    return;
  }
  abyssCampaignStatus.classList.remove("hidden");
  const title = node("div", "campaign-status-title", "Abyss campaign");
  setTooltip(title, "Persistent Four Against the Abyss campaign state saved outside a single dungeon session.");
  abyssCampaignStatus.appendChild(title);
  if (plot) {
    const active = node("div", "campaign-status-line", `${abyssPlotLabel(plot)}: ${abyssPlotNextStep(plot)}`);
    setTooltip(active, "This plot carries into the next Four Against the Abyss session until completed.");
    abyssCampaignStatus.appendChild(active);
  } else {
    const idle = node("div", "campaign-status-line muted", "No active Abyss plot.");
    setTooltip(idle, "Start a plot inside a Four Against the Abyss dungeon from the room panel.");
    abyssCampaignStatus.appendChild(idle);
  }
  if (sire) {
    const sireLine = node("div", "campaign-status-line", `Tracked vampire sire: ${sire.name}`);
    setTooltip(sireLine, "Start or resume a Four Against the Abyss session and use Hunt vampire sire to force the re-encounter.");
    abyssCampaignStatus.appendChild(sireLine);
  }
  if (completed.length) {
    const names = completed.slice(-3).map((item) => abyssPlotLabel(item)).join(", ");
    const done = node("div", "campaign-status-line muted", `Completed plots: ${names}`);
    setTooltip(done, "Most recent completed Abyss campaign plots saved in persistent campaign history.");
    abyssCampaignStatus.appendChild(done);
  }
}

function tagSettlementApothecaryAvailable(session) {
  if (!session?.tag_banking_enabled) return false;
  if (session.mode !== "exploration") return false;
  return (session.party || []).some((member) => {
    if (member.current_life <= 0) return false;
    const classId = String(member.class_id || "").toLowerCase();
    if (classId !== "wandering_alchemist" && classId !== "wandering alchemist") return false;
    return (member.inventory || []).some(
      (item) => /mortar/i.test(item) && /pestle/i.test(item)
    );
  });
}

function heroApothecaryBrews(member) {
  return (member.inventory || []).filter((item) => item.includes("(Apothecary"));
}

function courtshipPandoraBlocksPeaceful(session, template) {
  if (!courtshipHasPandora(session) || !template) return false;
  const exempt = new Set(["Lady of Lament", "Lady of Lament (illusion)"]);
  return !exempt.has(template);
}

function lexItemTooltip(session, member, itemName) {
  if (!session?.courtship_demesne_active) return null;
  const token = `${member.character_id}|${itemName}`;
  const granted = (session.courtship_lex_granted_items || []).includes(token);
  if (!granted) return null;
  const taxed = (session.courtship_lex_soul_taxed || []).includes(token);
  return taxed ? ACTION_TOOLTIPS.courtshipLexSoulTaxPaid : ACTION_TOOLTIPS.courtshipLexSoulTax;
}

function courtshipDemesneDisplay(session) {
  if (!session?.courtship_demesne_active) return "";
  const region = COURTSHIP_REGION_LABELS[session.courtship_demesne_region] || session.courtship_demesne_region || "Demesne";
  const melancholy = session.courtship_melancholy || {};
  const maxMel = Object.values(melancholy).reduce((a, b) => Math.max(a, b), 0);
  const keywords = (session.courtship_keywords || []).join(", ");
  let line = `Demesne: ${region}`;
  if (maxMel) line += ` · Melancholy ${maxMel}`;
  if (keywords) line += ` · ${keywords}`;
  if (courtshipHasPandora(session)) {
    line += " · PANDORA (fight to the death)";
  }
  const loverId = session.courtship_truelove_character_id;
  if (loverId) {
    const lover = (session.party || []).find((member) => member.character_id === loverId);
    if (lover) line += ` · TRUELOVE: ${lover.name}`;
  }
  return line;
}

function appendCourtshipDemesneActions(parent, session) {
  if (!session?.courtship_demesne_active || session.mode !== "exploration") return;
  const region = COURTSHIP_REGION_LABELS[session.courtship_demesne_region] || "Demesne";
  parent.appendChild(subline(`Blossoms' Demesne — ${region} (TCOTFD)`));
  if (courtshipHasPandora(session)) {
    const pandoraLine = subline(
      "PANDORA — flower demons fight to the death (+6 Reaction penalty; Lady of Lament exempt)."
    );
    setTooltip(pandoraLine, ACTION_TOOLTIPS.courtshipPandoraHostility);
    parent.appendChild(pandoraLine);
  }
  const pendingChoice = session.courtship_pending_choice;
  const wooLabel = session.courtship_woo_template || session.courtship_pending_choice_label || "flower demons";

  if (session.courtship_woo_active) {
    const wooTemplate = session.courtship_woo_template || "";
    const matronWoo = wooTemplate === "Matron of Summer";
    const ladyWoo = wooTemplate === "Lady of Lament";
    const stanceWoo = matronWoo || ladyWoo;
    parent.appendChild(
      subline(
        `Wooing ${wooLabel} — ${session.courtship_woo_successes || 0}/3 Giving successes` +
          (session.courtship_woo_dominant_stance ? " · dominant stance" : "") +
          (session.courtship_woo_passionate_stance
            ? matronWoo
              ? " · passionate stance"
              : " · romantic stance"
            : "") +
          (session.courtship_lady_keepsake_bonus ? " · keepsake +3 Giving" : "")
      )
    );
    if (stanceWoo) {
      const stanceLabel = node("label", matronWoo ? "courtship-passionate-toggle" : "courtship-romantic-toggle");
      const stanceBox = document.createElement("input");
      stanceBox.type = "checkbox";
      stanceBox.checked = Boolean(state.courtshipPassionateStance);
      stanceLabel.appendChild(stanceBox);
      stanceLabel.appendChild(
        document.createTextNode(matronWoo ? " Passionate stance" : " Romantic stance")
      );
      setTooltip(
        stanceLabel,
        matronWoo ? ACTION_TOOLTIPS.courtshipPassionateStance : ACTION_TOOLTIPS.courtshipRomanticStance
      );
      stanceBox.addEventListener("change", () => {
        state.courtshipPassionateStance = stanceBox.checked;
      });
      parent.appendChild(stanceLabel);
    } else {
      const dominantLabel = node("label", "courtship-dominant-toggle");
      const dominantBox = document.createElement("input");
      dominantBox.type = "checkbox";
      dominantBox.checked = Boolean(state.courtshipDominantStance);
      dominantBox.disabled = Boolean(session.courtship_woo_dominant_blocked);
      dominantLabel.appendChild(dominantBox);
      dominantLabel.appendChild(document.createTextNode(" Dominant stance"));
      setTooltip(
        dominantLabel,
        session.courtship_woo_dominant_blocked
          ? "Dominant stance blocked for this encounter (TCOTFD)."
          : ACTION_TOOLTIPS.courtshipDominantStance
      );
      dominantBox.addEventListener("change", () => {
        state.courtshipDominantStance = dominantBox.checked;
      });
      parent.appendChild(dominantLabel);
    }
    const wooParams = stanceWoo
      ? { courtship_passionate_stance: Boolean(state.courtshipPassionateStance) }
      : { courtship_dominant_stance: Boolean(state.courtshipDominantStance) };
    const wooSpeaker = (session.party || []).find(
      (member) => member.character_id === session.courtship_woo_speaker_id
    );
    if (
      wooSpeaker &&
      wooSpeaker.class_id === "halfling" &&
      luckPointsRemaining(session, wooSpeaker) > 0
    ) {
      const luckLabel = node("label", "courtship-luck-toggle");
      const luckBox = document.createElement("input");
      luckBox.type = "checkbox";
      luckBox.checked = Boolean(state.courtshipUseLuck);
      luckLabel.appendChild(luckBox);
      luckLabel.appendChild(document.createTextNode(" Spend Luck on failed roll"));
      setTooltip(luckLabel, ACTION_TOOLTIPS.courtshipWooLuck);
      luckBox.addEventListener("change", () => {
        state.courtshipUseLuck = luckBox.checked;
      });
      parent.appendChild(luckLabel);
      wooParams.courtship_use_luck = Boolean(state.courtshipUseLuck);
    }
    const givingBtn = node("button", "secondary", "Giving roll");
    givingBtn.type = "button";
    setButtonTooltip(givingBtn, ACTION_TOOLTIPS.courtshipWooGiving);
    givingBtn.addEventListener("click", () =>
      advance("courtship_woo_giving", {
        ...wooParams,
        courtship_use_luck: Boolean(state.courtshipUseLuck),
      })
    );
    parent.appendChild(givingBtn);
    const withholdBtn = node("button", "secondary", "Withholding roll");
    withholdBtn.type = "button";
    setButtonTooltip(withholdBtn, ACTION_TOOLTIPS.courtshipWooWithholding);
    withholdBtn.addEventListener("click", () =>
      advance("courtship_woo_withholding", {
        ...wooParams,
        courtship_use_luck: Boolean(state.courtshipUseLuck),
      })
    );
    parent.appendChild(withholdBtn);
    if (
      session.courtship_libidinal_reroll_available &&
      session.courtship_libidinal_character_id === session.courtship_woo_speaker_id
    ) {
      const libidinalBtn = node("button", "secondary", "Libidinal re-roll Giving (1 Life)");
      libidinalBtn.type = "button";
      setButtonTooltip(libidinalBtn, ACTION_TOOLTIPS.courtshipLibidinalReroll);
      libidinalBtn.addEventListener("click", () => advance("courtship_libidinal_reroll"));
      parent.appendChild(libidinalBtn);
    }
    if (session.courtship_damsel_penalty_pending) {
      const lifeBtn = node("button", "secondary", "Next Withholding fail: lose 1 Life");
      lifeBtn.type = "button";
      setButtonTooltip(lifeBtn, ACTION_TOOLTIPS.courtshipDamselPenaltyLife);
      lifeBtn.addEventListener("click", () => advance("courtship_damsel_penalty", { courtship_damsel_penalty: "life" }));
      parent.appendChild(lifeBtn);
      const madnessBtn = node("button", "secondary", "Next Withholding fail: gain 1 Madness");
      madnessBtn.type = "button";
      setButtonTooltip(madnessBtn, ACTION_TOOLTIPS.courtshipDamselPenaltyMadness);
      madnessBtn.addEventListener("click", () =>
        advance("courtship_damsel_penalty", { courtship_damsel_penalty: "madness" })
      );
      parent.appendChild(madnessBtn);
    }
    const fightBtn = node("button", "secondary", "Fight instead");
    fightBtn.type = "button";
    setButtonTooltip(fightBtn, ACTION_TOOLTIPS.courtshipWooAbortFight);
    fightBtn.addEventListener("click", () => advance("courtship_woo_abort_fight"));
    parent.appendChild(fightBtn);
    return;
  }

  if (pendingChoice === "woo_or_fight") {
    const label = session.courtship_pending_choice_label || "flower demons";
    if (
      label === "Lady of Lament" &&
      (session.courtship_keywords || []).includes("KEEPSAKE") &&
      !session.courtship_lady_keepsake_bonus
    ) {
      const keepsakeBtn = node("button", "secondary", "Present Keepsake (+3 Giving)");
      keepsakeBtn.type = "button";
      setButtonTooltip(keepsakeBtn, ACTION_TOOLTIPS.courtshipLadyKeepsake);
      keepsakeBtn.addEventListener("click", () => advance("courtship_lady_keepsake"));
      parent.appendChild(keepsakeBtn);
    }
    if (
      label === "Matron of Summer" &&
      session.courtship_matron_head_quest_active &&
      (session.party || []).some((member) =>
        (member.inventory || []).some((item) => /lady of lament's head/i.test(String(item)))
      )
    ) {
      const headBtn = node("button", "secondary", "Deliver Lady's head");
      headBtn.type = "button";
      setButtonTooltip(headBtn, ACTION_TOOLTIPS.courtshipMatronDeliverHead);
      headBtn.addEventListener("click", () =>
        advance("courtship_book_choice", { courtship_choice: "deliver" })
      );
      parent.appendChild(headBtn);
    }
    if (courtshipPandoraBlocksPeaceful(session, label)) {
      parent.appendChild(
        subline("PANDORA — wooing is impossible; fight to the death (BoS entry 2, TCOTFD).")
      );
      const fightBtn = node("button", "secondary", "Fight to the death");
      fightBtn.type = "button";
      setButtonTooltip(fightBtn, ACTION_TOOLTIPS.courtshipFightDemons);
      fightBtn.addEventListener("click", () => advance("courtship_fight_encounter"));
      parent.appendChild(fightBtn);
      return;
    }
    const wooBtn = node("button", "secondary", `Woo ${label}`);
    wooBtn.type = "button";
    setButtonTooltip(wooBtn, ACTION_TOOLTIPS.courtshipWooDemons);
    wooBtn.addEventListener("click", () => advance("courtship_woo_encounter"));
    parent.appendChild(wooBtn);
    const fightBtn = node("button", "secondary", "Fight");
    fightBtn.type = "button";
    setButtonTooltip(fightBtn, ACTION_TOOLTIPS.courtshipFightDemons);
    fightBtn.addEventListener("click", () => advance("courtship_fight_encounter"));
    parent.appendChild(fightBtn);
    return;
  }
  if (pendingChoice === "seduce_or_fight") {
    const label = session.courtship_pending_choice_label || "flower demons";
    if (courtshipPandoraBlocksPeaceful(session, label)) {
      parent.appendChild(
        subline("PANDORA — seduce reaction skipped; fight to the death (BoS entry 2, TCOTFD).")
      );
      const fightBtn = node("button", "secondary", "Fight to the death");
      fightBtn.type = "button";
      setButtonTooltip(fightBtn, ACTION_TOOLTIPS.courtshipSeduceFight);
      fightBtn.addEventListener("click", () =>
        advance("courtship_seduce_reaction", { courtship_choice: "fight" })
      );
      parent.appendChild(fightBtn);
      return;
    }
    const seduceBtn = node("button", "secondary", `Roll seduce reaction (${label})`);
    seduceBtn.type = "button";
    setButtonTooltip(seduceBtn, ACTION_TOOLTIPS.courtshipSeduceReaction);
    seduceBtn.addEventListener("click", () => advance("courtship_seduce_reaction"));
    parent.appendChild(seduceBtn);
    const fightBtn = node("button", "secondary", "Fight to the death");
    fightBtn.type = "button";
    setButtonTooltip(fightBtn, ACTION_TOOLTIPS.courtshipSeduceFight);
    fightBtn.addEventListener("click", () =>
      advance("courtship_seduce_reaction", { courtship_choice: "fight" })
    );
    parent.appendChild(fightBtn);
    return;
  }
  if (pendingChoice === "occlith") {
    const attackBtn = node("button", "secondary", "Attack the Occlith");
    attackBtn.type = "button";
    setButtonTooltip(attackBtn, ACTION_TOOLTIPS.courtshipOcclithAttack);
    attackBtn.addEventListener("click", () => advance("courtship_occlith_choice", { courtship_choice: "attack" }));
    parent.appendChild(attackBtn);
    const parleyBtn = node("button", "secondary", "Parley with the Occlith");
    parleyBtn.type = "button";
    setButtonTooltip(parleyBtn, ACTION_TOOLTIPS.courtshipOcclithParley);
    parleyBtn.addEventListener("click", () => advance("courtship_occlith_choice", { courtship_choice: "parley" }));
    parent.appendChild(parleyBtn);
    return;
  }
  if (pendingChoice === "lady_of_lament") {
    if ((session.courtship_keywords || []).includes("KEEPSAKE")) {
      const keepsakeBtn = node("button", "secondary", "Present Keepsake");
      keepsakeBtn.type = "button";
      setButtonTooltip(keepsakeBtn, ACTION_TOOLTIPS.courtshipLadyOfLamentKeepsake);
      keepsakeBtn.addEventListener("click", () => advance("courtship_lady_of_lament_choice", { courtship_choice: "keepsake" }));
      parent.appendChild(keepsakeBtn);
    }
    const leaveBtn = node("button", "secondary", "Withdraw respectfully");
    leaveBtn.type = "button";
    setButtonTooltip(leaveBtn, ACTION_TOOLTIPS.courtshipLadyOfLamentLeave);
    leaveBtn.addEventListener("click", () => advance("courtship_lady_of_lament_choice", { courtship_choice: "leave" }));
    parent.appendChild(leaveBtn);
    return;
  }
  if (pendingChoice === "disturbing_altar") {
    const cluesBtn = node("button", "secondary", "Gain d3 Clues");
    cluesBtn.type = "button";
    setButtonTooltip(cluesBtn, ACTION_TOOLTIPS.courtshipDisturbingAltarClues);
    cluesBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "clues" }));
    parent.appendChild(cluesBtn);
    const madnessBtn = node("button", "secondary", "Gain 1 Madness");
    madnessBtn.type = "button";
    setButtonTooltip(madnessBtn, ACTION_TOOLTIPS.courtshipDisturbingAltarMadness);
    madnessBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "madness" }));
    parent.appendChild(madnessBtn);
    return;
  }
  if (pendingChoice === "queens_vault") {
    const heedBtn = node("button", "secondary", "Heed warning — leave vault");
    heedBtn.type = "button";
    setButtonTooltip(heedBtn, ACTION_TOOLTIPS.courtshipQueensVaultHeed);
    heedBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "heed" }));
    parent.appendChild(heedBtn);
    if ((session.courtship_keywords || []).includes("ACERBIC")) {
      const acerbicBtn = node("button", "secondary", "Break lock (ACERBIC)");
      acerbicBtn.type = "button";
      setButtonTooltip(acerbicBtn, ACTION_TOOLTIPS.courtshipQueensVaultAcerbic);
      acerbicBtn.addEventListener("click", () =>
        advance("courtship_book_choice", { courtship_choice: "acerbic" })
      );
      parent.appendChild(acerbicBtn);
    }
    return;
  }
  if (pendingChoice === "lex_cambion") {
    const soulBtn = node("button", "secondary", "Trade soul cube (pick 3 items)");
    soulBtn.type = "button";
    setButtonTooltip(soulBtn, ACTION_TOOLTIPS.courtshipLexSoulCube);
    soulBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "soul_cube" }));
    parent.appendChild(soulBtn);
    const goldBtn = node("button", "secondary", "Buy for 300gp (pick 3 items)");
    goldBtn.type = "button";
    setButtonTooltip(goldBtn, ACTION_TOOLTIPS.courtshipLexGold);
    goldBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "buy" }));
    parent.appendChild(goldBtn);
    const attackBtn = node("button", "secondary", "Attack Lex the Cambion");
    attackBtn.type = "button";
    setButtonTooltip(attackBtn, "BoS entry 7 — fight Lex; double natural 6s on Attack and Defense curse with Tamas Zeya (TCOTFD).");
    attackBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "attack" }));
    parent.appendChild(attackBtn);
    return;
  }
  if (pendingChoice === "lex_cambion_pick") {
    const remaining = session.courtship_lex_picks_remaining || 0;
    parent.appendChild(subline(`Lex the Cambion — pick ${remaining} more item(s) (BoS entry 32, TCOTFD).`));
    const catalog = state.rulesTables?.courtship_lex_shop_table || [];
    for (const row of catalog) {
      const taken = (session.courtship_lex_picks_taken || []).includes(row.key);
      const pickBtn = node("button", "secondary", row.item);
      pickBtn.type = "button";
      pickBtn.disabled = taken;
      setButtonTooltip(pickBtn, `${row.source || "TCOTFD"} — ${ACTION_TOOLTIPS.courtshipLexPickItem}`);
      pickBtn.addEventListener("click", () =>
        advance("courtship_book_choice", { courtship_choice: row.key })
      );
      parent.appendChild(pickBtn);
    }
    return;
  }
  if (pendingChoice === "matron_head_deliver") {
    const deliverBtn = node("button", "secondary", "Deliver Lady of Lament's head");
    deliverBtn.type = "button";
    setButtonTooltip(deliverBtn, ACTION_TOOLTIPS.courtshipMatronDeliverHead);
    deliverBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "deliver" })
    );
    parent.appendChild(deliverBtn);
    return;
  }
  if (pendingChoice === "matron_head_reward") {
    const epicBtn = node("button", "secondary", "Epic Rewards (d6 roll)");
    epicBtn.type = "button";
    setButtonTooltip(epicBtn, ACTION_TOOLTIPS.courtshipMatronEpicReward);
    epicBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "epic" })
    );
    parent.appendChild(epicBtn);
    const blossoms = [
      ["1", "Magic Shovel"],
      ["2", "Talisman of Impotence"],
      ["3", "Karmic Calcinator"],
      ["4", "Enchanted Alembic"],
      ["5", "Mortar of Souls"],
      ["6", "Foldable Pavilion"],
    ];
    for (const [roll, item] of blossoms) {
      const pickBtn = node("button", "secondary", item);
      pickBtn.type = "button";
      setButtonTooltip(pickBtn, `Blossoms Magic Item table roll ${roll} (BoS entry 8, TCOTFD).`);
      pickBtn.addEventListener("click", () =>
        advance("courtship_book_choice", { courtship_choice: roll })
      );
      parent.appendChild(pickBtn);
    }
    return;
  }
  if (pendingChoice === "aetheric_conversion") {
    parent.appendChild(subline("Ætheric Conversion — choose the rare ingredient to synthesize (TCOTFD p.27)."));
    for (const name of [
      "Colleen's ambergris",
      "Death orchid petals",
      "Enraptured heart",
      "Tears of solace",
      "Blooded roses",
      "Lolly",
      "Pandalatra's feather",
    ]) {
      const pickBtn = node("button", "secondary", name);
      pickBtn.type = "button";
      setButtonTooltip(pickBtn, ACTION_TOOLTIPS.courtshipAethericConversion);
      pickBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: name }));
      parent.appendChild(pickBtn);
    }
    return;
  }
  if (pendingChoice === "song_of_charm") {
    parent.appendChild(subline("Song of Charm — choose the monsters' reaction (TCOTFD p.27)."));
    for (const reaction of ["fight", "bribe", "trade_information", "quest", "offer_information", "sleep"]) {
      const label = reaction.replace(/_/g, " ");
      const pickBtn = node("button", "secondary", label);
      pickBtn.type = "button";
      setButtonTooltip(pickBtn, ACTION_TOOLTIPS.courtshipSongOfCharm);
      pickBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: reaction }));
      parent.appendChild(pickBtn);
    }
    return;
  }
  if (pendingChoice === "flower_portal_destination") {
    parent.appendChild(subline("Flower Portal — choose destination (TCOTFD p.27)."));
    const enterBtn = node("button", "secondary", "Enter the Demesne (1 soul cube)");
    enterBtn.type = "button";
    setButtonTooltip(enterBtn, ACTION_TOOLTIPS.courtshipFlowerPortalEnter);
    enterBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "enter_demesne" })
    );
    parent.appendChild(enterBtn);
    const leaveBtn = node("button", "secondary", "Leave the Demesne (1 soul cube)");
    leaveBtn.type = "button";
    setButtonTooltip(leaveBtn, ACTION_TOOLTIPS.courtshipFlowerPortalLeave);
    leaveBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "leave_demesne" })
    );
    parent.appendChild(leaveBtn);
    const netherBtn = node("button", "secondary", "Netherworld portal (3 soul cubes + L9 roll)");
    netherBtn.type = "button";
    setButtonTooltip(netherBtn, ACTION_TOOLTIPS.courtshipFlowerPortalNetherworld);
    netherBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "netherworld" })
    );
    parent.appendChild(netherBtn);
    return;
  }
  if (pendingChoice === "bountiful_harvest") {
    const commonBtn = node("button", "secondary", "Bountiful Harvest — common (d6)");
    commonBtn.type = "button";
    setButtonTooltip(commonBtn, ACTION_TOOLTIPS.courtshipBountifulHarvestCommon);
    commonBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "common" })
    );
    parent.appendChild(commonBtn);
    const uncommonBtn = node("button", "secondary", "Bountiful Harvest — uncommon (d3)");
    uncommonBtn.type = "button";
    setButtonTooltip(uncommonBtn, ACTION_TOOLTIPS.courtshipBountifulHarvestUncommon);
    uncommonBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "uncommon" })
    );
    parent.appendChild(uncommonBtn);
    return;
  }
  if (pendingChoice === "shovel_substitute") {
    const tier = session.courtship_shovel_substitute_tier === "uncommon" ? "uncommon" : "common";
    const options =
      tier === "uncommon" ? BLOSSOMS_UNCOMMON_SUBSTITUTES : BLOSSOMS_COMMON_SUBSTITUTES;
    parent.appendChild(
      subline(`Magic Shovel — substitute for ${session.courtship_pending_choice_label || "harvested ingredient"}`)
    );
    for (const option of options) {
      const pickBtn = node("button", "secondary", option);
      pickBtn.type = "button";
      setButtonTooltip(pickBtn, ACTION_TOOLTIPS.courtshipShovelSubstitute);
      pickBtn.addEventListener("click", () =>
        advance("courtship_book_choice", { courtship_choice: option })
      );
      parent.appendChild(pickBtn);
    }
    return;
  }
  if (pendingChoice === "mistress_quest_ingredients") {
    const deliverBtn = node("button", "secondary", "Deliver 3 rare ingredients");
    deliverBtn.type = "button";
    setButtonTooltip(deliverBtn, ACTION_TOOLTIPS.courtshipMistressQuest);
    deliverBtn.addEventListener("click", () =>
      advance("courtship_book_choice", { courtship_choice: "deliver" })
    );
    parent.appendChild(deliverBtn);
    return;
  }
  if (pendingChoice === "maze_lost") {
    const clueBtn = node("button", "secondary", "Spend 1 Clue — escape maze");
    clueBtn.type = "button";
    setButtonTooltip(clueBtn, ACTION_TOOLTIPS.courtshipMazeClue);
    clueBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "clue" }));
    parent.appendChild(clueBtn);
    const wanderBtn = node("button", "secondary", "Wander (+1 Melancholy each)");
    wanderBtn.type = "button";
    setButtonTooltip(wanderBtn, ACTION_TOOLTIPS.courtshipMazeWander);
    wanderBtn.addEventListener("click", () => advance("courtship_book_choice", { courtship_choice: "wander" }));
    parent.appendChild(wanderBtn);
    return;
  }
  if (pendingChoice === "apothecary_brew") {
    parent.appendChild(subline("Apothecary Cookbook — choose a recipe (TCOTFD p.7-9)."));
    const catalog = state.rulesTables?.courtship_apothecary_recipes_table || [];
    for (const recipe of catalog) {
      const label = `${recipe.name} (${recipe.cost_gp || 0}gp)`;
      const recipeBtn = node("button", "secondary", label);
      recipeBtn.type = "button";
      const difficulty = Number(recipe.difficulty || 0);
      const rollHint = difficulty > 0 ? ` · d6+L vs ${difficulty}` : " · auto success";
      setButtonTooltip(
        recipeBtn,
        `${recipe.summary || recipe.item || recipe.name}${rollHint} — ${ACTION_TOOLTIPS.courtshipApothecaryRecipe}`
      );
      recipeBtn.addEventListener("click", () =>
        advance("courtship_brew_apothecary", { courtship_choice: recipe.key })
      );
      parent.appendChild(recipeBtn);
    }
    return;
  }
  const pathways = session.courtship_pending_pathways || [];
  if (pathways.length) {
    for (const dest of pathways) {
      const btn = node("button", "secondary", `Travel to ${COURTSHIP_REGION_LABELS[dest] || dest}`);
      btn.type = "button";
      setButtonTooltip(btn, ACTION_TOOLTIPS.courtshipPathwayTravel);
      btn.addEventListener("click", () => advance("courtship_choose_pathway", { courtship_region: dest }));
      parent.appendChild(btn);
    }
    const stayBtn = node("button", "secondary", "Stay in this region");
    stayBtn.type = "button";
    setButtonTooltip(stayBtn, ACTION_TOOLTIPS.courtshipStayRegion);
    stayBtn.addEventListener("click", () => advance("courtship_choose_pathway", { courtship_region: session.courtship_demesne_region }));
    parent.appendChild(stayBtn);
    if ((session.clues_found || 0) >= 1) {
      const trailBtn = node("button", "secondary", "Spend 1 Clue — secret trail");
      trailBtn.type = "button";
      setButtonTooltip(trailBtn, ACTION_TOOLTIPS.courtshipSecretTrailClue);
      trailBtn.addEventListener("click", () => advance("courtship_secret_trail_clue"));
      parent.appendChild(trailBtn);
    }
    return;
  }
  if (courtshipApothecaryBrewAvailable(session)) {
    const brewBtn = node("button", "secondary", "Brew Apothecary recipe");
    brewBtn.type = "button";
    setButtonTooltip(brewBtn, ACTION_TOOLTIPS.courtshipApothecaryBrew);
    brewBtn.addEventListener("click", () => advance("courtship_brew_apothecary"));
    parent.appendChild(brewBtn);
  }
  const rollBtn = node("button", "secondary", "Roll Demesne encounter (2d6)");
  rollBtn.type = "button";
  setButtonTooltip(rollBtn, ACTION_TOOLTIPS.courtshipRollEncounter);
  rollBtn.addEventListener("click", () => advance("courtship_roll_encounter"));
  parent.appendChild(rollBtn);
  if ((session.clues_found || 0) >= 1 && !session.courtship_encounter_reroll_spent) {
    const clueBtn = node("button", "secondary", "Spend 1 Clue — re-roll encounter");
    clueBtn.type = "button";
    setButtonTooltip(clueBtn, ACTION_TOOLTIPS.courtshipSpendEncounterClue);
    clueBtn.addEventListener("click", () => advance("courtship_spend_encounter_clue", { courtship_encounter_shift: "reroll" }));
    parent.appendChild(clueBtn);
  }
  if (session.courtship_demesne_region === "seaside" || session.courtship_demesne_region === "riverside") {
    const standalone = session.adventure_id === "courtship-demesne" || session.courtship_entry_source === "standalone";
    const fromFlower = session.courtship_entry_source === "flower_portal";
    let leaveLabel = "Flower Portal — return to FD";
    let leaveTooltip = ACTION_TOOLTIPS.courtshipLeaveDemesneFd;
    if (standalone) {
      leaveLabel = "Flower Portal — end adventure";
      leaveTooltip = ACTION_TOOLTIPS.courtshipLeaveDemesneStandalone;
    } else if (fromFlower) {
      leaveLabel = "Flower Portal — return to Norindaal";
      leaveTooltip = ACTION_TOOLTIPS.courtshipFlowerPortalLeave;
    }
    const leaveBtn = node("button", "secondary", leaveLabel);
    leaveBtn.type = "button";
    setButtonTooltip(leaveBtn, leaveTooltip);
    leaveBtn.addEventListener("click", () => advance("courtship_leave_demesne"));
    parent.appendChild(leaveBtn);
  }
}

function isHeroicSacrificeItem(item) {
  return isFdQuestMagicItem(item);
}

function eligibleHeroicSacrificeItems(session) {
  const items = [];
  for (const member of livingParty(session)) {
    for (const item of member.inventory || []) {
      if (isHeroicSacrificeItem(item) && !items.includes(item)) items.push(item);
    }
  }
  return items;
}

function appendFdDarkPitsSpellPicker(parent, session, quest) {
  if (!parent || quest?.key !== "fd_dark_pits") return;
  const claimStatus = questClaimStatus(session, quest);
  if (!claimStatus.ok) return;
  const row = node("div", "fd-dark-pits-spell-row");
  row.appendChild(node("span", "search-label", "Dark Pits scroll reward:"));
  const select = document.createElement("select");
  select.className = "fd-dark-pits-spell-select";
  for (const spell of fdRewardSpellNames()) {
    const option = document.createElement("option");
    option.value = spell;
    option.textContent = spell;
    select.appendChild(option);
  }
  row.appendChild(select);
  const claimBtn = node("button", "secondary", "Claim with chosen spell");
  claimBtn.type = "button";
  setButtonTooltip(claimBtn, ACTION_TOOLTIPS.claimFdDarkPitsReward);
  claimBtn.addEventListener("click", () =>
    advance("claim_fd_quest_reward", {
      spell_name: select.value,
      fd_quest_id: quest.quest_id,
    })
  );
  row.appendChild(claimBtn);
  parent.appendChild(row);
}

function appendFdCyclopeanIdolActions(parent, session, tile) {
  if (session?.ruleset !== "forsaken_depths" || session.mode !== "exploration" || !tile) return;
  const pending = session.fd_idol_pending_choice;
  if (pending === "secret_clue") {
    const clueBtn = node("button", "secondary", "Open secret door (1 Clue)");
    clueBtn.type = "button";
    setButtonTooltip(clueBtn, ACTION_TOOLTIPS.fdIdolSecretClue);
    clueBtn.addEventListener("click", () => advance("choose_fd_idol_outcome", { fd_idol_choice: "secret_clue" }));
    parent.appendChild(clueBtn);
    const searchBtn = node("button", "secondary", "Search for secret door");
    searchBtn.type = "button";
    setButtonTooltip(searchBtn, ACTION_TOOLTIPS.fdIdolSecretSearch);
    searchBtn.addEventListener("click", () => advance("choose_fd_idol_outcome", { fd_idol_choice: "secret_search" }));
    parent.appendChild(searchBtn);
    return;
  }
  if (pending === "lady_in_black") {
    const items = eligibleHeroicSacrificeItems(session);
    if (items.length) {
      const row = node("div", "fd-sacrifice-row");
      row.appendChild(node("span", "search-label", "Sacrifice Heroic item:"));
      const select = document.createElement("select");
      select.className = "fd-sacrifice-select";
      for (const item of items) {
        const option = document.createElement("option");
        option.value = item;
        option.textContent = item;
        select.appendChild(option);
      }
      row.appendChild(select);
      const sacrificeBtn = node("button", "secondary", "Sacrifice (1 Clue + Quest)");
      sacrificeBtn.type = "button";
      setButtonTooltip(sacrificeBtn, ACTION_TOOLTIPS.fdIdolSacrifice);
      sacrificeBtn.addEventListener("click", () =>
        advance("choose_fd_idol_outcome", { fd_idol_choice: "lady_sacrifice", item_name: select.value })
      );
      row.appendChild(sacrificeBtn);
      parent.appendChild(row);
    } else {
      parent.appendChild(node("div", "item muted", "No Heroic magic item in party inventory to sacrifice."));
    }
    const questBtn = node("button", "secondary", "Roll Forsaken Depths Quest Table");
    questBtn.type = "button";
    setButtonTooltip(questBtn, ACTION_TOOLTIPS.fdIdolQuestRoll);
    questBtn.addEventListener("click", () =>
      advance("choose_fd_idol_outcome", { fd_idol_choice: "lady_quest_roll" })
    );
    parent.appendChild(questBtn);
    return;
  }
  if (pending === "heroic_learn") {
    const learnBtn = node("button", "secondary", `Learn ${session.fd_idol_heroic_spell || "spell"} (1 XP roll)`);
    learnBtn.type = "button";
    setButtonTooltip(learnBtn, ACTION_TOOLTIPS.fdIdolHeroicLearn);
    learnBtn.addEventListener("click", () => advance("choose_fd_idol_outcome", { fd_idol_choice: "heroic_learn" }));
    parent.appendChild(learnBtn);
    return;
  }
  if (tile.fd_cyclopean_idol_available && !tile.fd_cyclopean_idol_resolved) {
    const idolBtn = node("button", "secondary", "Interact with Cyclopean Idol");
    idolBtn.type = "button";
    setButtonTooltip(idolBtn, ACTION_TOOLTIPS.resolveFdCyclopeanIdol);
    idolBtn.addEventListener("click", () => advance("resolve_fd_cyclopean_idol"));
    parent.appendChild(idolBtn);
  }
}

function isFdQuestMagicItem(item) {
  const lower = String(item || "").trim().toLowerCase();
  if (!lower) return false;
  if (lower.startsWith("legendary ") || lower.includes("humming crystal")) return true;
  if (!lower.includes("magic ")) return false;
  return ["armor", "wand", "ring", "weapon", "shield"].some((token) => lower.includes(token));
}

function eligibleFdQuestTurnInItems(session, quest) {
  if (!quest || quest.key !== "fd_three_items") return [];
  const snapshot = quest.fd_quest_inventory_snapshot || {};
  const heldAtAccept = new Set();
  for (const items of Object.values(snapshot)) {
    for (const item of items || []) heldAtAccept.add(item);
  }
  const eligible = [];
  for (const member of livingParty(session)) {
    for (const item of member.inventory || []) {
      if (!eligible.includes(item) && isFdQuestMagicItem(item) && !heldAtAccept.has(item)) {
        eligible.push(item);
      }
    }
  }
  return eligible;
}

function appendFdQuestActions(parent, session, tile, quest) {
  if (!parent || session?.ruleset !== "forsaken_depths" || session.mode !== "exploration" || !quest) return;
  if (!quest?.key?.startsWith("fd_")) return;
  const questId = quest.quest_id;

  if (
    quest.key === "fd_defeat_enemy" &&
    !quest.fd_quest_enemy_defeated &&
    !quest.fd_quest_enemy_spawned
  ) {
    const enemyBtn = node("button", "secondary", "Spend 1 Clue: summon quest enemy");
    enemyBtn.type = "button";
    setButtonTooltip(enemyBtn, ACTION_TOOLTIPS.fdQuestSpendClueEnemy);
    enemyBtn.addEventListener("click", () => advance("fd_quest_spend_clue_enemy", { fd_quest_id: questId }));
    parent.appendChild(enemyBtn);
  }
  if (
    quest.key === "fd_servitor" &&
    !quest.fd_quest_servitor_found &&
    !quest.fd_quest_servitor_pending_room
  ) {
    const servitorBtn = node("button", "secondary", "Spend 2 Clues: servitor in next room");
    servitorBtn.type = "button";
    setButtonTooltip(servitorBtn, ACTION_TOOLTIPS.fdQuestSpendCluesServitor);
    servitorBtn.addEventListener("click", () => advance("fd_quest_spend_clues_servitor", { fd_quest_id: questId }));
    parent.appendChild(servitorBtn);
  }
  if (
    quest.key === "fd_lost_pages" &&
    (quest.fd_quest_pages_found || 0) < (quest.fd_quest_pages_required || 4)
  ) {
    for (const member of livingParty(session)) {
      for (const item of member.inventory || []) {
        if (!isScrollItem(item)) continue;
        const pageBtn = node("button", "secondary", `Count scroll as lost page: ${item}`);
        pageBtn.type = "button";
        setButtonTooltip(pageBtn, ACTION_TOOLTIPS.recoverFdLostPage);
        pageBtn.addEventListener("click", () =>
          advance("recover_fd_lost_page", { item_name: item, fd_quest_from_treasure: false, fd_quest_id: questId })
        );
        parent.appendChild(pageBtn);
      }
    }
  }
  if (
    quest.key === "fd_three_items" &&
    tile?.id === quest.tile_id &&
    (quest.fd_quest_items_turned_in || 0) < (quest.fd_quest_items_required || 3)
  ) {
    const items = eligibleFdQuestTurnInItems(session, quest);
    if (items.length) {
      const turnInRow = node("div", "fd-quest-turnin-row");
      const select = document.createElement("select");
      select.className = "fd-quest-turnin-select";
      for (const item of items) {
        const option = document.createElement("option");
        option.value = item;
        option.textContent = item;
        select.appendChild(option);
      }
      turnInRow.appendChild(select);
      const turnInBtn = node("button", "secondary", "Turn in magic item");
      turnInBtn.type = "button";
      setButtonTooltip(turnInBtn, ACTION_TOOLTIPS.turnInFdQuestItem);
      turnInBtn.addEventListener("click", () =>
        advance("turn_in_fd_quest_item", { item_name: select.value, fd_quest_id: questId })
      );
      turnInRow.appendChild(turnInBtn);
      parent.appendChild(turnInRow);
    }
  }
}

function fdPrisonersEscapeAvailable(session) {
  return (
    session?.ruleset === "forsaken_depths" &&
    session.fd_side_sheet_active &&
    session.fd_citadel_type === "prisoners_citadel" &&
    session.mode === "exploration"
  );
}

function fdSideSheetEntryAvailable(session, tile) {
  if (
    !tile ||
    session?.ruleset !== "forsaken_depths" ||
    session.fd_side_sheet_active ||
    tile.fd_side_sheet_entry_used
  ) {
    return null;
  }
  const codes = tile.room_codes || [];
  if (codes.includes("Ru")) return "ruins";
  if (codes.includes("ETC") || (session.fd_citadel_entry_tile_id === tile.id && session.fd_citadel_type)) {
    return "citadel";
  }
  return null;
}

