startSession.addEventListener("click", async () => {
  try {
    const party_id = partySelect.value;
    const adventure_id = adventureSelect.value || "random";
    writeStartSetupPrefs();
    if (adventure_id === "ai-adventure") {
      setStatus(
        "AI Adventure builds a prompt only. Import JSON below, then select the installed module from the adventure dropdown to play."
      );
      return;
    }
    if (!party_id) {
      setStatus("Create a party first");
      return;
    }
    const party = state.parties.find((item) => item.id === party_id);
    if (party && partyHasBusyMembers(party)) {
      setStatus("One or more party members are already in an active adventure.");
      return;
    }
    state.session = await api("/api/sessions", {
      method: "POST",
      body: JSON.stringify({
        party_id,
        adventure_id,
        xp_system: xpSystemSelect?.value || "classical",
        map_bounds_mode: mapBoundsSelect?.value || "unlimited",
        unlimited_map_element_cap: resolveUnlimitedMapElementCap(),
        fiendish_foes_enabled: resolveFiendishFoesEnabledForAdventure(adventure_id),
        start_camped_outside: Boolean(startCampedOutside?.checked),
        ruleset_profile_id:
          adventure_id === "random"
            ? rulesetSelect?.value || "ee_random"
            : adventure_id === "courtship-demesne"
              ? "courtship_demesne"
              : "ee_random",
      }),
    });
    writeActiveSessionId(state.session.id);
    resetSessionRenderCache();
    syncSessionListFromSession(state.session, { render: setupViewVisible() });
    markSetupRosterDirty();
    setStatus("Session started");
    renderSession();
  } catch (error) {
    handleError(error);
  }
});

