const EXPLORATION_COMMAND_HINT =
  "look · exits · go north 1 (n1) · open west 2 · listen east 1 · search · claim · fight · rest · eat · help";
const CAMP_COMMAND_HINT = "eat · eat <name> · eat all · help";
const COMBAT_COMMAND_HINT = "foes · target N · resolve · flee · reaction · help";

function renderExplorationCommandBar(session) {
  if (!explorationCommandBar) return;
  const camped = Boolean(session?.camped_outside);
  const exploration =
    session &&
    effectiveSessionMode(session) === "exploration" &&
    !camped &&
    session.mode !== "complete";
  const campedExplore = session && camped && session.mode === "exploration";
  const combat =
    session &&
    session.mode === "combat" &&
    livingFoesOnTile(session).length > 0 &&
    session.mode !== "complete";
  const show = exploration || combat || campedExplore;
  explorationCommandBar.classList.toggle("hidden", !show);
  if (!show) return;
  if (explorationCommandHints) {
    explorationCommandHints.textContent = combat
      ? COMBAT_COMMAND_HINT
      : campedExplore
        ? CAMP_COMMAND_HINT
        : EXPLORATION_COMMAND_HINT;
  }
  const busy = Boolean(state.sessionActionPending);
  if (explorationCommandInput) {
    explorationCommandInput.title = combat
      ? "Type a combat command and press Enter. Try: foes, target 1, resolve, flee."
      : campedExplore
        ? "Camp commands: eat, eat <hero name>, eat all."
        : "Type a command and press Enter. " +
          "Directions match exit labels (North 1, East 2). Aliases: n/s/e/w + number.";
  }
  const submit = explorationCommandForm?.querySelector('button[type="submit"]');
  if (submit) submit.disabled = busy;
}

function parseExitCommandTokens(input) {
  const trimmed = String(input || "").trim();
  if (!trimmed) return null;
  const lower = trimmed.toLowerCase();
  const verbMatch = lower.match(/^(go|open|listen)\s+(.+)$/);
  const verb = verbMatch ? verbMatch[1] : "go";
  const rest = verbMatch ? verbMatch[2] : lower;
  const compact = rest.replace(/\s+/g, "");
  const dirMatch = compact.match(/^(north|south|east|west|n|s|e|w)(\d+)?$/i);
  if (!dirMatch) return null;
  const dirMap = { n: "north", s: "south", e: "east", w: "west" };
  const direction = dirMap[dirMatch[1]] || dirMatch[1];
  const index = dirMatch[2] ? Number.parseInt(dirMatch[2], 10) : 1;
  if (!Number.isFinite(index) || index < 1) return null;
  return { verb, direction, index };
}

function findFacingExitByLabel(session, tile, direction, index) {
  if (!tile) return null;
  const sideLabels = exitSideLabels(tile);
  const target = `${titleCase(direction)} ${index}`;
  const facing = playerFacingExits(session, tile);
  return facing.find((exit) => sideLabels.get(exit.id) === target) || null;
}

function appendLocalCommandNote(message) {
  if (!sessionLog || !message) return;
  const line = document.createElement("div");
  line.className = "log-line log-line-command";
  line.textContent = message;
  sessionLog.appendChild(line);
  sessionLog.scrollTop = sessionLog.scrollHeight;
}

function listExitCommands(session, tile) {
  const sideLabels = exitSideLabels(tile);
  const facing = playerFacingExits(session, tile);
  if (!facing.length) {
    appendLocalCommandNote("No usable exits from here.");
    return;
  }
  const parts = facing.map((exit) => {
    const label = sideLabels.get(exit.id) || titleCase(exit.direction);
    const door =
      exit.kind === "door" ? (exit.door_open ? "open door" : "closed door") : exit.kind;
    return `${label} (${door})`;
  });
  appendLocalCommandNote(`Exits: ${parts.join("; ")}`);
}

async function executeCombatCommand(rawInput) {
  const session = state.session;
  if (!session || session.mode !== "combat") {
    setStatus("Combat commands are only available during combat.");
    return false;
  }
  const input = String(rawInput || "").trim();
  if (!input) return false;
  const lower = input.toLowerCase();
  const tile = currentTile(session);
  const livingFoes = (tile?.enemies || []).filter((foe) => foe.life > 0);

  if (lower === "help" || lower === "?") {
    appendLocalCommandNote(`Combat commands: ${COMBAT_COMMAND_HINT}`);
    return true;
  }
  if (lower === "foes" || lower === "targets") {
    const labels = buildFoeDisplayLabels(livingFoes);
    if (!livingFoes.length) {
      appendLocalCommandNote("No living foes.");
      return true;
    }
    const parts = livingFoes.map(
      (foe, index) => `${index + 1}. ${labels.get(foe.id) || foe.name}`
    );
    appendLocalCommandNote(`Foes: ${parts.join("; ")}`);
    return true;
  }
  const targetMatch = lower.match(/^target\s+(\d+)$/);
  if (targetMatch) {
    const index = Number.parseInt(targetMatch[1], 10) - 1;
    const foe = livingFoes[index];
    if (!foe) {
      setStatus(`No foe at target ${targetMatch[1]}. Type foes for a list.`);
      return false;
    }
    for (const member of (session.party || []).filter((hero) => hero.current_life > 0)) {
      state.combatTargets[member.character_id] = foe.id;
    }
    const label = buildFoeDisplayLabels(livingFoes).get(foe.id) || foe.name;
    appendLocalCommandNote(`All heroes target ${label}.`);
    return true;
  }
  if (lower === "resolve" || lower === "round" || lower === "fight" || lower === "combat") {
    resolveCombatRound();
    return true;
  }
  if (lower === "flee" || lower === "run") {
    await advance("flee");
    return true;
  }
  if (lower === "reaction" || lower === "check reaction") {
    await advance("check_reaction");
    return true;
  }
  if (lower === "start combat") {
    await advance("start_combat");
    return true;
  }
  setStatus(`Unknown combat command: ${input}. Type help for a list.`);
  return false;
}

async function executeEatCommand(rawInput) {
  const session = state.session;
  if (!session || !canEatRations(session)) {
    setStatus("Food rations can be eaten during exploration or while camped outside.");
    return false;
  }
  const input = String(rawInput || "").trim();
  const lower = input.toLowerCase();
  if (lower === "eat" || lower === "eat ration" || lower === "eat food") {
    const leadId = leadMemberId(session);
    if (!leadId) {
      setStatus("No living hero to feed.");
      return false;
    }
    await advance("eat_food_ration", { character_id: leadId });
    return true;
  }
  if (lower === "eat all" || lower === "feed hungry" || lower === "feed") {
    promptFeedHungryHeroes(session, { feedAll: true });
    return true;
  }
  const nameMatch = lower.match(/^eat\s+(.+)$/);
  if (nameMatch) {
    const member = findPartyMemberByName(session, nameMatch[1]);
    if (!member) {
      setStatus(`No living hero matches "${nameMatch[1]}".`);
      return false;
    }
    await advance("eat_food_ration", { character_id: member.character_id });
    return true;
  }
  return false;
}

async function executeExplorationCommand(rawInput) {
  const session = state.session;
  if (!session) return false;
  if (session.mode === "combat" && livingFoesOnTile(session).length > 0) {
    return executeCombatCommand(rawInput);
  }
  if (session.camped_outside && session.mode === "exploration") {
    const input = String(rawInput || "").trim();
    if (!input) return false;
    const lower = input.toLowerCase();
    if (lower === "help" || lower === "?") {
      appendLocalCommandNote(`Camp commands: ${CAMP_COMMAND_HINT}`);
      return true;
    }
    if (lower.startsWith("eat") || lower === "feed" || lower === "feed hungry") {
      return executeEatCommand(rawInput);
    }
    setStatus(`Unknown camp command: ${input}. Type help for eat commands.`);
    return false;
  }
  if (effectiveSessionMode(session) !== "exploration") {
    setStatus("Commands are only available during exploration.");
    return false;
  }
  const input = String(rawInput || "").trim();
  if (!input) return false;
  const lower = input.toLowerCase();
  const tile = currentTile(session);

  if (lower === "help" || lower === "?") {
    appendLocalCommandNote(
      "Commands: look · exits · go <dir> <n> · open <dir> <n> · listen <dir> <n> · search · claim · fight · rest · eat · eat <name> · eat all"
    );
    return true;
  }
  if (lower === "look" || lower === "l") {
    await advance("look");
    return true;
  }
  if (lower === "exits" || lower === "exit") {
    listExitCommands(session, tile);
    return true;
  }
  if (lower === "search") {
    await advance("search");
    return true;
  }
  if (lower === "claim" || lower === "claim treasure") {
    await advance("claim_treasure");
    return true;
  }
  if (lower === "fight" || lower === "combat" || lower === "start combat") {
    await advance("start_combat");
    return true;
  }
  if (lower === "rest") {
    await advance("rest");
    return true;
  }
  if (lower.startsWith("eat") || lower === "feed" || lower === "feed hungry") {
    return executeEatCommand(rawInput);
  }

  const parsed = parseExitCommandTokens(input);
  if (!parsed) {
    setStatus(`Unknown command: ${input}. Type help for a list.`);
    return false;
  }
  const exit = findFacingExitByLabel(session, tile, parsed.direction, parsed.index);
  if (!exit) {
    setStatus(`No exit ${titleCase(parsed.direction)} ${parsed.index} from here.`);
    return false;
  }
  if (parsed.verb === "go") {
    if (exit.kind === "door" && !exit.door_open) {
      setStatus(`${titleCase(parsed.direction)} ${parsed.index} is a closed door — try open ${parsed.direction} ${parsed.index}.`);
      return false;
    }
    runTravelExit(session, exit);
    return true;
  }
  if (parsed.verb === "open" || parsed.verb === "listen") {
    const options = collectDoorActionOptions(session, exit);
    const action = parsed.verb === "listen" ? "listen_at_door" : "open_door";
    const option = options.find((item) => item.action === action && !item.disabled);
    if (!option) {
      setStatus(`No hero can ${parsed.verb} ${titleCase(parsed.direction)} ${parsed.index}.`);
      return false;
    }
    await advance(action, { exit_id: exit.id, character_id: option.characterId });
    return true;
  }
  return false;
}

async function advance(action, extra = {}) {
  if (!state.session) return false;
  if (state.sessionActionPending) return false;
  if (!beginSessionAction(action)) return false;
  const wasCampedOutside = Boolean(state.session.camped_outside);
  const wasCombat = state.session?.mode === "combat";
  let succeeded = false;
  try {
    state.session = await api(`/api/sessions/${state.session.id}/advance`, {
      method: "POST",
      body: JSON.stringify({
        action,
        show_rolls: state.showRolls,
        explain_math: state.showMath,
        ...extra,
      }),
    });
    syncCampaignFromServer().catch(() => {});
    state.pendingScoutId = null;
    writeActiveSessionId(state.session.id);
    syncSessionListFromSession(state.session, { render: setupViewVisible() });
    if (state.session.mode === "complete") {
      const report = buildAdventureCloseoutReport(state.session);
      saveLastAdventureReport(report);
      clearActiveSessionId();
      state.session = null;
      writeActiveView("setup");
      await reloadCharacters({ render: false });
      showSetupView();
      if (report.party_id) state.selectedPartyId = report.party_id;
      renderParties();
      setStatus("Adventure complete — character roster updated");
      showAdventureCloseoutModal(report);
      succeeded = true;
      return true;
    } else {
      if (state.session.camped_outside || wasCampedOutside) {
        await reloadCharacters({ render: setupViewVisible() });
      }
      if (action === "spend_banked_xp" || action === "xp_roll") {
        const lines = (state.session.log || []).slice(-4).map((entry) => String(entry).trim()).filter(Boolean);
        setStatus(lines.length ? lines.join(" · ") : "Session updated");
      } else {
        setStatus("Session updated");
      }
    }
    renderSession();
    maybePromptFeedAfterCombat(state.session, wasCombat);
    succeeded = true;
    return true;
  } catch (error) {
    handleError(error);
    return false;
  } finally {
    endSessionAction({ restoreDisabled: !succeeded });
  }
}

